mapper.sql:
WHERE archived = #{filter.archived}

    AND (strpos(lower(title), lower(#{filter.q})) > 0
      OR strpos(lower(paper_id), lower(#{filter.q})) > 0
      OR strpos(lower(authors), lower(#{filter.q})) > 0
      OR strpos(lower(doi), lower(#{filter.q})) > 0)

AND source_id = #{filter.sourceId}
AND year >= #{filter.yearFrom}
AND year <= #{filter.yearTo}
AND status = #{filter.status}

mapper.select:
SELECT paper_id, title, authors FROM v2_paper WHERE source_id = #{sourceId} AND publication_year = #{year}
UNION ALL
SELECT file_id, paper_title, authors FROM original_file WHERE source_id = #{sourceId} AND year = #{year}
ORDER BY paper_id

SELECT paper_id FROM v2_paper_read WHERE NOT archived AND source_id = #{sourceId}
AND year >= #{yearFrom}
AND year <= #{yearTo}
ORDER BY paper_id LIMIT #{limit}

mapper.update:
UPDATE v2_paper SET archived_at = CASE WHEN #{archived} THEN now() ELSE NULL END,
                    record_version = record_version + 1, updated_at = now()
WHERE paper_id = #{id}
